/** 两个录入入口共用日历日期校验，错误代码用于表单和导入行提示。 */
export function validateSurveyDate(value, today) {
  if (typeof value !== 'string' || !/^\d{4}-\d{2}-\d{2}$/.test(value)) return 'INVALID_DATE';
  const parsed = new Date(`${value}T00:00:00.000Z`);
  if (Number.isNaN(parsed.valueOf()) || parsed.toISOString().slice(0, 10) !== value) return 'INVALID_DATE';
  return null;
}

import { validateSurveyDate } from './dateRules.js';

/** 新增失败返回字段错误；成功时保留调用者给出的其他字段。 */
export function createSurvey(input, today) {
  const error = validateSurveyDate(input.surveyDate, today);
  return error ? { ok: false, fieldErrors: { surveyDate: error } }
    : { ok: true, record: { ...input } };
}

import { validateSurveyDate } from './dateRules.js';

/** 导入保持按行部分成功；无效日期只影响所属行，不改变其他记录。 */
export function importSurveys(rows, today) {
  const inserted = [];
  const errors = [];
  rows.forEach((record, index) => {
    const code = validateSurveyDate(record.surveyDate, today);
    if (code) errors.push({ row: index + 1, field: 'surveyDate', code });
    else inserted.push({ ...record });
  });
  return { inserted, errors };
}

import assert from 'node:assert/strict';
import { test } from 'node:test';
import { createSurvey } from './create.js';
import { importSurveys } from './import.js';

test('新增保留有效日历日期和其他字段', () => {
  const input = { id: 'synthetic-a', surveyDate: '2026-10-26', category: 'sample' };
  assert.deepEqual(createSurvey(input, '2026-10-27'), { ok: true, record: input });
});

test('导入按行返回无效日历日期，保留其他有效行', () => {
  const first = { id: 'synthetic-a', surveyDate: '2026-10-26' };
  assert.deepEqual(importSurveys([first, { surveyDate: '2026-02-30' }], '2026-10-27'), {
    inserted: [first], errors: [{ row: 2, field: 'surveyDate', code: 'INVALID_DATE' }],
  });
});

